nd_time\":0,\"enabled\":true,\"permanent\":true},{\"activity_id\":2101,\"begin_time\":1791302400,\"end_time\":0,\"enabled\":true,\"permanent\":true},{\"activity_id\":2201,\"begin_time\":1791302400,\"end_time\":0,\"enabled\":true,\"permanent\":true},{\"activity_id\":2401,\"begin_time\":1791302400,\"end_time\":0,\"enabled\":true,\"permanent\":true}]")
