    # HS_CLIENT_DIAGNOSTIC_BEGIN
    # -*- coding: utf-8 -*-
    """将原生Python异常和ERROR日志关联到服务器角色；保留原错误处理。"""

    def _install_hs_client_diagnostic():
        import sys
        import time
        import logging
        import traceback
        import gworld
        if getattr(logging, '_hs_client_diagnostic_revision', 0) >= 1:
            return
        state = {'sending': False, 'window': 0, 'count': 0, 'seen': {}}

        def report(message):
            if state['sending']:
                return
            now = time.time()
            if now - state['window'] >= 60:
                state['window'], state['count'], state['seen'] = now, 0, {}
            message = message[:6000]
            if state['count'] >= 10 or message in state['seen']:
                return
            player = gworld.get_player()
            if player is None or getattr(player, 'server_proxy', None) is None:
                return
            state['sending'] = True
            try:
                player.server_proxy.client_sa_log('hs_client_error', {'message': message})
                state['seen'][message] = True
                state['count'] += 1
            except Exception:
                # 诊断投递失败不改变或递归调用原生错误处理。
                pass
            finally:
                state['sending'] = False

        class DiagnosticHandler(logging.Handler):
            def emit(self, record):
                try:
                    report(self.format(record))
                except Exception:
                    pass

        handler = DiagnosticHandler(logging.ERROR)
        logging.getLogger().addHandler(handler)
        original = sys.excepthook
        def exception_hook(kind, value, trace):
            try:
                report(''.join(traceback.format_exception(kind, value, trace)))
            except Exception:
                pass
            return original(kind, value, trace)
        sys.excepthook = exception_hook
        logging._hs_client_diagnostic_revision = 1
        print('HS_CLIENT_DIAGNOSTIC_READY 1')

    _install_hs_client_diagnostic()

    # HS_CLIENT_DIAGNOSTIC_END


    # HS_SUMMON_TIMER_BEGIN
    # -*- coding: utf-8 -*-
    """保留原生卡池时间候选，将无终点的逐日搜索改为次日重新查询。"""


    def _install_hs_summon_timer():
        import sys
        import game3d
        import gworld
        import data
        from utils import time_utils
        from guis import gui_utils
        module = sys.modules.get('guis.summon_card.summon_new_card')
        if module is None:
            return False
        cls = module.summon_new_card
        if getattr(cls, '_hs_summon_timer_revision', 0) >= 1:
            return True

        def start_refresh_timer(self):
            if self.refresh_callback:
                self.refresh_callback.cancel()
                self.refresh_callback = None
            now_time = time_utils.now_time()
            target_time = None

            def candidate(value):
                if value > now_time:
                    return value
                return None

            for pool_id in self.get_valid_card_pool():
                pool_data = data.cards_random[pool_id]
                player = gworld.get_player()
                begin_time = player.get_card_pool_time(pool_id)
                times = []
                if begin_time > 0 and pool_data.invalid_time:
                    times.append(candidate(begin_time + pool_data.invalid_time * 86400))
                if pool_data.open_server_days:
                    times.append(candidate(time_utils.next_interval_day_refresh_time(
                        player.server_open_time, None, pool_data.open_server_days)))
                open_time, close_time = gui_utils.get_pool_open_close_time(pool_id)
                if not open_time and not close_time:
                    # 原生在检查开启窗口前已计算失效/开服候选，不能丢弃。
                    for value in times:
                        if value is not None and (target_time is None or value < target_time):
                            target_time = value
                    continue
                open_timestamp = sum(open_time) if open_time else None
                if open_timestamp and open_timestamp > now_time:
                    times.append(open_timestamp)
                else:
                    if close_time:
                        times.append(candidate(sum(close_time)))
                    # 原生索引可能恒为-1或只有一个轮转项，不能循环到2038年。
                    # 次日询问原生ask_refresh即可重新读取实际卡池，不改变抽卡权威。
                    if pool_data.cycle_flag:
                        times.append(candidate(time_utils.next_daily_timestamp(
                            now_time, time_utils.REFRESH_HMS)))
                for value in times:
                    if value is not None and (target_time is None or value < target_time):
                        target_time = value
            if target_time is not None:
                self.refresh_callback = self.add_callback(target_time - now_time, self.ask_refresh)

        cls.start_refresh_timer = start_refresh_timer
        cls._hs_summon_timer_revision = 1
        print('HS_SUMMON_TIMER_READY 1')
        return True


